-- Tables of the shared drafts (MariaDB 10.6+ / MySQL 8), equivalent to the mapping of
-- Janalis\Collaborate\Entity\{Draft,DraftField,DraftEvent}. Copy them into a migration of the application.
CREATE TABLE collaborate_draft (id VARCHAR(64) NOT NULL, generation INT NOT NULL, revision INT NOT NULL, saved_revision INT NOT NULL, bytes INT NOT NULL, record_id VARCHAR(255) DEFAULT NULL, saved_by INT DEFAULT NULL, saved_by_label VARCHAR(255) DEFAULT NULL, updated_at DATETIME(6) NOT NULL, INDEX collaborate_draft_updated_at (updated_at), PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_unicode_ci`;
CREATE TABLE collaborate_draft_event (draft_id VARCHAR(64) NOT NULL, revision INT NOT NULL, batch_id VARCHAR(64) NOT NULL COLLATE `utf8mb4_bin`, field LONGTEXT NOT NULL COLLATE `utf8mb4_bin`, payload JSON NOT NULL, UNIQUE INDEX collaborate_draft_event_batch (draft_id, batch_id), PRIMARY KEY (draft_id, revision)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_unicode_ci`;
CREATE TABLE collaborate_draft_field (draft_id VARCHAR(64) NOT NULL, name VARCHAR(512) NOT NULL COLLATE `utf8mb4_bin`, type VARCHAR(16) NOT NULL, state JSON NOT NULL, PRIMARY KEY (draft_id, name)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_unicode_ci`;

-- Tables of the notifications (notifications.enabled), equivalent to the mapping of
-- Janalis\Collaborate\Notification\Entity\{Notification,NotificationPreference,PushSubscription}, which is mapped
-- only while they are on. A recipient is the id of the collaborator provider: add a foreign key to the user table of
-- the application (ON DELETE CASCADE) in its own migration if it wants one.
CREATE TABLE collaborate_notification (id INT AUTO_INCREMENT NOT NULL, read_at DATETIME DEFAULT NULL, recipient_id INT NOT NULL, topic VARCHAR(64) NOT NULL, type VARCHAR(64) NOT NULL, parameters JSON NOT NULL, url VARCHAR(2048) DEFAULT NULL, created_at DATETIME NOT NULL, message_key CHAR(36) DEFAULT NULL, INDEX collaborate_notification_latest (recipient_id, created_at), INDEX collaborate_notification_cursor (recipient_id, id), UNIQUE INDEX collaborate_notification_message (message_key), PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_unicode_ci`;
CREATE TABLE collaborate_notification_preference (recipient_id INT NOT NULL, topic VARCHAR(64) NOT NULL, subscribed TINYINT NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (recipient_id, topic)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_unicode_ci`;
CREATE TABLE collaborate_push_subscription (id INT AUTO_INCREMENT NOT NULL, endpoint_hash CHAR(64) NOT NULL, last_used_at DATETIME DEFAULT NULL, recipient_id INT NOT NULL, endpoint LONGTEXT NOT NULL, p256dh VARCHAR(255) NOT NULL, auth VARCHAR(255) NOT NULL, encoding VARCHAR(16) NOT NULL, created_at DATETIME NOT NULL, INDEX collaborate_push_subscription_recipient (recipient_id), UNIQUE INDEX collaborate_push_subscription_endpoint (endpoint_hash), PRIMARY KEY (id)) DEFAULT CHARACTER SET utf8mb4 COLLATE `utf8mb4_unicode_ci`;
